-- =====================================================================
--  032 — Skin cleansing panels: what people are saying, positive and
--        negative
--
--  Each "What's behind this" panel now splits what people are saying into
--  positive and negative, each with a short read of what that side is
--  about and up to six consumer lines, translated where needed, with no
--  names. Where a brand has fewer lines on one side (Pears has almost no
--  negative conversation), it shows what there is and says so.
--
--  Run after 031. Safe to re-run.
-- =====================================================================

begin;

update sov_panels set content = content || jsonb_build_object('voices', '{"positive": {"insight": "Positive conversation about Unilever brands is mostly warm reactions to campaign stars and stories, with loyal users praising Lux''s body wash and Pears as a product.", "quotes": [{"text": "That''s my favourite body wash that I use on a daily basis.", "translated": false, "kind": "praise"}, {"text": "I use it too, it''s really good.", "translated": true, "kind": "praise"}, {"text": "Best product.", "translated": false, "kind": "praise"}, {"text": "Really useful.", "translated": false, "kind": "praise"}, {"text": "We watched it today. Lovely.", "translated": true, "kind": "praise"}, {"text": "Enjoyed the content! All the very best!", "translated": false, "kind": "reaction"}]}, "negative": {"insight": "Negative conversation targets the campaigns rather than the soaps: the Lux film was called boring and a waste of money, and the Lifebuoy pageant drew criticism of its presenters and creators.", "quotes": [{"text": "You should be paid to watch the film. I feel I wasted my time watching it.", "translated": true, "kind": "complaint"}, {"text": "There are better imported brands than Lux, and those are what they actually use.", "translated": true, "kind": "comparison"}, {"text": "Why does the person who spoke first in the video have a fake Australian accent? Who did the PR for this?", "translated": false, "kind": "complaint"}, {"text": "Sad that you''re forced to promote a product, I guess you had no choice.", "translated": false, "kind": "complaint"}, {"text": "What''s the impact on sales? Wasting money.", "translated": false, "kind": "complaint"}, {"text": "I use baby soap. I''m not wasting money on that rubbish.", "translated": true, "kind": "comparison"}]}}'::jsonb, 'quotes', '[]'::jsonb)
 where period_id = (select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18') and panel_key = 'section:share';
