update sov_panels set content = content || jsonb_build_object('voices', '{"positive": {"insight": "People are most positive about scent and feel: Velvet and Rani are praised for fragrance that lasts, and loyal users speak up for Lux, Pears and Khomba.", "quotes": [{"text": "Velvet really smells lovely, the pink one.", "translated": true, "kind": "praise"}, {"text": "Rani''s purple soap smells amazing too. The scent lasts until the bar is finished.", "translated": true, "kind": "praise"}, {"text": "Velvet, you should know I''ve been your customer for about a decade.", "translated": false, "kind": "praise"}, {"text": "Best product.", "translated": false, "kind": "praise"}, {"text": "I use it too, it''s really good.", "translated": true, "kind": "praise"}, {"text": "Khomba is the best too.", "translated": true, "kind": "praise"}]}, "negative": {"insight": "Complaints split in two: product problems for competitors, such as skin reactions to Calin and bars that melt or lose their scent, and campaign criticism for Lux and Lifebuoy.", "quotes": [{"text": "Please don''t use Calin. All of us got a rash and suffered for months.", "translated": true, "kind": "complaint"}, {"text": "They say Calin isn''t good for the skin. And it''s no longer the round shape it used to be, it''s an odd shape and melts quickly.", "translated": true, "kind": "complaint"}, {"text": "Velvet melts away quickly when you use it.", "translated": true, "kind": "complaint"}, {"text": "In the first days it had a lovely lavender scent, but now that scent is gone.", "translated": true, "kind": "complaint"}, {"text": "You should be paid to watch the film. I feel I wasted my time watching it.", "translated": true, "kind": "complaint"}, {"text": "Why does the person who spoke first in the video have a fake Australian accent? Who did the PR for this?", "translated": false, "kind": "complaint"}]}}'::jsonb, 'quotes', '[]'::jsonb)
 where period_id = (select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18') and panel_key = 'section:sentiment';
update sov_panels set content = content || jsonb_build_object('voices', '{"positive": {"insight": "Praise in the category is about visible results, such as glow, fewer pimples and fading marks, mostly for local herbal soaps sold online.", "quotes": [{"text": "Chandanalepa is the best. I love its Ayurvedic, cinnamon, sandalwood and charcoal ones.", "translated": true, "kind": "praise"}, {"text": "Honestly, after using it for just one day I got a glow. Now I''m a daily customer.", "translated": true, "kind": "praise"}, {"text": "My pimples have really gone down a lot now.", "translated": true, "kind": "praise"}, {"text": "The soap melts less, so you can use it for many days.", "translated": true, "kind": "praise"}, {"text": "Of course this is really good. I had a mark on my hand that nothing would remove, and now I can''t even find it.", "translated": true, "kind": "praise"}, {"text": "Really very good. Refreshing.", "translated": true, "kind": "praise"}]}, "negative": {"insight": "Complaints are as much about buying as about the soap: sellers not replying, orders not arriving and rising prices, alongside dryness and doubts about natural claims.", "quotes": [{"text": "The soap is good. But the price going up month after month is the problem.", "translated": true, "kind": "complaint"}, {"text": "In my personal experience it''s not good for the face. It made my face dry and my skin started to peel.", "translated": false, "kind": "complaint"}, {"text": "They call it a bleaching soap and then say it''s natural.", "translated": true, "kind": "complaint"}, {"text": "You never check your messages.", "translated": true, "kind": "complaint"}, {"text": "My order hasn''t arrived.", "translated": true, "kind": "complaint"}, {"text": "I bought it because everyone said it''s good, but the bits in the soap feel like they scratch my skin as it melts.", "translated": true, "kind": "complaint"}]}}'::jsonb, 'quotes', '[]'::jsonb)
