update sov_panels set content = content || jsonb_build_object('voices', '{"positive": {"insight": "Fans like Lux''s scent and body wash, and part of the audience enjoyed the film and its stars.", "quotes": [{"text": "That''s my favourite body wash that I use on a daily basis.", "translated": false, "kind": "praise"}, {"text": "I use it too, it''s really good.", "translated": true, "kind": "praise"}, {"text": "We watched it today. Lovely.", "translated": true, "kind": "praise"}, {"text": "The film is lovely.", "translated": true, "kind": "praise"}, {"text": "Love this! I bet it smells so good.", "translated": false, "kind": "praise"}, {"text": "She''s lovely, wow. I''m buying it straight away.", "translated": true, "kind": "purchase intent"}]}, "negative": {"insight": "Most criticism is of the film tie-in: viewers found it boring or strange and questioned the spend, and some doubt the ambassadors really use Lux.", "quotes": [{"text": "You should be paid to watch the film. I feel I wasted my time watching it.", "translated": true, "kind": "complaint"}, {"text": "There are better imported brands than Lux, and those are what they actually use.", "translated": true, "kind": "comparison"}, {"text": "What''s the impact on sales? Wasting money.", "translated": false, "kind": "complaint"}, {"text": "Your film is really boring, it didn''t work for me at all. Don''t bother going to watch it. A waste of time, I could have watched Spider-Man.", "translated": true, "kind": "complaint"}, {"text": "Do you really use these?", "translated": false, "kind": "question"}, {"text": "Doing so many activities, and the competitors are doing well.", "translated": false, "kind": "complaint"}]}}'::jsonb, 'quotes', '[]'::jsonb)
 where period_id = (select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18') and panel_key = 'brand:Lux';
update sov_panels set content = content || jsonb_build_object('voices', '{"positive": {"insight": "Positive reaction is mostly support for the Mister Sri Lanka contestants rather than talk about the soap.", "quotes": [{"text": "Enjoyed the content! All the very best!", "translated": false, "kind": "reaction"}, {"text": "Let''s go, this is so nice. Keep it up.", "translated": false, "kind": "reaction"}, {"text": "Nice one, brother.", "translated": false, "kind": "reaction"}, {"text": "Well done.", "translated": false, "kind": "reaction"}, {"text": "Creatine no, Lifebuoy yes.", "translated": false, "kind": "reaction"}]}, "negative": {"insight": "Criticism targets how the campaign was delivered: accents, scripted lines and contestants who seemed forced to promote.", "quotes": [{"text": "Why does the person who spoke first in the video have a fake Australian accent? Who did the PR for this?", "translated": false, "kind": "complaint"}, {"text": "Sad that you''re forced to promote a product, I guess you had no choice.", "translated": false, "kind": "complaint"}, {"text": "Why did I hear ''looking like cheap''?", "translated": false, "kind": "complaint"}, {"text": "You need to speak slower.", "translated": false, "kind": "complaint"}, {"text": "I use baby soap. I''m not wasting money on that rubbish.", "translated": true, "kind": "comparison"}, {"text": "Copy and paste.", "translated": false, "kind": "complaint"}]}}'::jsonb, 'quotes', '[]'::jsonb)
