update sov_panels set content = content || jsonb_build_object('voices', '{"positive": {"insight": "Velvet''s fans talk about its scents, especially pink, rosehip and vanilla, and many are long-time users.", "quotes": [{"text": "Velvet really smells lovely, the pink one.", "translated": true, "kind": "praise"}, {"text": "If it''s not Velvet, there''s no point bathing.", "translated": true, "kind": "praise"}, {"text": "Velvet, you should know I''ve been your customer for about a decade.", "translated": false, "kind": "praise"}, {"text": "The smell of vanilla and shea butter.", "translated": false, "kind": "praise"}, {"text": "And Velvet rosehip is so good.", "translated": false, "kind": "praise"}, {"text": "Velvet rose soap, the cream one, and Velvet body wash. I can''t remember how long I''ve been using them.", "translated": true, "kind": "praise"}]}, "negative": {"insight": "Negative conversation about Velvet is rare; the one complaint that stands out is that the bar melts quickly.", "quotes": [{"text": "Velvet melts away quickly when you use it.", "translated": true, "kind": "complaint"}]}}'::jsonb, 'quotes', '[]'::jsonb)
