update sov_panels set content = content || jsonb_build_object('voices', '{"positive": {"insight": "One person praises Calin''s hair and body soap but says it is now hard to find.", "quotes": [{"text": "Calin''s hair and body soap suited my hair and my greying slowed down. But now you can''t even find that soap.", "translated": true, "kind": "praise"}]}, "negative": {"insight": "Negative conversation is about skin reactions, with people warning others not to use it.", "quotes": [{"text": "Please don''t use Calin. All of us got a rash and suffered for months.", "translated": true, "kind": "complaint"}, {"text": "They say Calin isn''t good for the skin. And it''s no longer the round shape it used to be, it''s an odd shape and melts quickly.", "translated": true, "kind": "complaint"}, {"text": "My sister got a rash on her neck while using Calin. The doctor said Calin isn''t good at all.", "translated": true, "kind": "complaint"}]}}'::jsonb, 'quotes', '[]'::jsonb)
