update sov_panels set content = content || jsonb_build_object('voices', '{"positive": {"insight": "Too little consumer conversation about Goya to quote this period.", "quotes": []}, "negative": {"insight": "", "quotes": []}}'::jsonb, 'quotes', '[]'::jsonb)
 where period_id = (select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18') and panel_key = 'brand:Goya';
update sov_panels set content = content || jsonb_build_object('voices', '{"positive": {"insight": "Too little consumer conversation about Dettol to quote this period.", "quotes": []}, "negative": {"insight": "", "quotes": []}}'::jsonb, 'quotes', '[]'::jsonb)
 where period_id = (select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18') and panel_key = 'brand:Dettol';

commit;

select panel_key,
       jsonb_array_length(content->'voices'->'positive'->'quotes') as positive_lines,
       jsonb_array_length(content->'voices'->'negative'->'quotes') as negative_lines
  from sov_panels where period_id = (select period_id from sov_periods where category_id = 'skin_cleansing' and period_start = '2026-07-20' and period_end = '2026-10-18')
 order by panel_key;
